// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Create a care group; caller becomes Admin
	// (POST /care-groups)
	CreateCareGroup(w http.ResponseWriter, r *http.Request)
	// Invite a user to the care group by email (admin only)
	// (POST /care-groups/{careGroupId}/invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request, careGroupId string)
	// Revoke a pending invitation (admin only)
	// (DELETE /care-groups/{careGroupId}/invitations/{token})
	RevokeInvitation(w http.ResponseWriter, r *http.Request, careGroupId string, token string)
	// List the members of a care group (any member)
	// (GET /care-groups/{careGroupId}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, careGroupId string)
	// Add a receiver to a care group (admin only)
	// (POST /care-groups/{careGroupId}/receivers)
	CreateReceiver(w http.ResponseWriter, r *http.Request, careGroupId string)
	// Return evaluated feature flags
	// (GET /flags)
	GetFlags(w http.ResponseWriter, r *http.Request)
	// Health check
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Pending invitations for the caller's verified email
	// (GET /invitations/mine)
	ListMyInvitations(w http.ResponseWriter, r *http.Request)
	// Accept an invitation by token; creates a membership
	// (POST /invitations/{token}/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request, token string)
	// Current user and their care-group memberships
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// List receivers across the caller's groups (optionally one group)
	// (GET /receivers)
	ListReceivers(w http.ResponseWriter, r *http.Request, params ListReceiversParams)
	// Archive a receiver (admin only)
	// (DELETE /receivers/{receiverId})
	ArchiveReceiver(w http.ResponseWriter, r *http.Request, receiverId string)
	// Get a receiver
	// (GET /receivers/{receiverId})
	GetReceiver(w http.ResponseWriter, r *http.Request, receiverId string)
	// Update a receiver (admin only)
	// (PATCH /receivers/{receiverId})
	UpdateReceiver(w http.ResponseWriter, r *http.Request, receiverId string)
	// List a receiver's scheduled items across trackers, soonest first (paginated)
	// (GET /receivers/{receiverId}/scheduled-items)
	ListReceiverScheduledItems(w http.ResponseWriter, r *http.Request, receiverId string, params ListReceiverScheduledItemsParams)
	// List a receiver's trackers
	// (GET /receivers/{receiverId}/trackers)
	ListTrackers(w http.ResponseWriter, r *http.Request, receiverId string)
	// Create a tracker for a receiver (admin only)
	// (POST /receivers/{receiverId}/trackers)
	CreateTracker(w http.ResponseWriter, r *http.Request, receiverId string)
	// Delete a scheduled item
	// (DELETE /scheduled-items/{scheduledItemId})
	DeleteScheduledItem(w http.ResponseWriter, r *http.Request, scheduledItemId string)
	// Get a single scheduled item
	// (GET /scheduled-items/{scheduledItemId})
	GetScheduledItem(w http.ResponseWriter, r *http.Request, scheduledItemId string)
	// Reschedule or edit a scheduled item
	// (PUT /scheduled-items/{scheduledItemId})
	UpdateScheduledItem(w http.ResponseWriter, r *http.Request, scheduledItemId string)
	// List the seeded tracker-template catalog
	// (GET /tracker-templates)
	ListTrackerTemplates(w http.ResponseWriter, r *http.Request)
	// Archive a tracker (admin only)
	// (DELETE /trackers/{trackerId})
	ArchiveTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// Get a tracker
	// (GET /trackers/{trackerId})
	GetTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// Update a tracker (admin only)
	// (PATCH /trackers/{trackerId})
	UpdateTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// List a tracker's events, newest first (paginated)
	// (GET /trackers/{trackerId}/events)
	ListEvents(w http.ResponseWriter, r *http.Request, trackerId string, params ListEventsParams)
	// Log an event against a tracker
	// (POST /trackers/{trackerId}/events)
	LogEvent(w http.ResponseWriter, r *http.Request, trackerId string)
	// Delete a logged event
	// (DELETE /trackers/{trackerId}/events/{eventId})
	DeleteEvent(w http.ResponseWriter, r *http.Request, trackerId string, eventId string)
	// Get a single event
	// (GET /trackers/{trackerId}/events/{eventId})
	GetEvent(w http.ResponseWriter, r *http.Request, trackerId string, eventId string)
	// Edit a logged event
	// (PATCH /trackers/{trackerId}/events/{eventId})
	UpdateEvent(w http.ResponseWriter, r *http.Request, trackerId string, eventId string)
	// List a tracker's scheduled items, soonest first (paginated)
	// (GET /trackers/{trackerId}/scheduled-items)
	ListScheduledItems(w http.ResponseWriter, r *http.Request, trackerId string, params ListScheduledItemsParams)
	// Add a scheduled item to a scheduled tracker
	// (POST /trackers/{trackerId}/scheduled-items)
	CreateScheduledItem(w http.ResponseWriter, r *http.Request, trackerId string)
	// Delete this entry? — Delete, on a logged or skipped entry
	// (DELETE /v1/entries/{entryId})
	DeleteEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// Entry detail — one entry, in whatever state it is in
	// (GET /v1/entries/{entryId})
	GetEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// Edit entry — Save, on a logged or skipped entry
	// (PUT /v1/entries/{entryId})
	ChangeEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// Log it — record a scheduled or unrecorded entry
	// (POST /v1/entries/{entryId}/log)
	LogEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// Skip — settle a scheduled or unrecorded entry as not happening
	// (POST /v1/entries/{entryId}/skip)
	SkipEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// Join a care team as a caregiver, by invite code
	// (POST /v1/invitations/redeem)
	RedeemInvitation(w http.ResponseWriter, r *http.Request)
	// Delete this note? — Delete
	// (DELETE /v1/journal-notes/{noteId})
	DeleteJournalNote(w http.ResponseWriter, r *http.Request, noteId string)
	// One journal note
	// (GET /v1/journal-notes/{noteId})
	GetJournalNote(w http.ResponseWriter, r *http.Request, noteId string)
	// Edit journal note — Save
	// (PUT /v1/journal-notes/{noteId})
	ChangeJournalNote(w http.ResponseWriter, r *http.Request, noteId string)
	// The signed-in caregiver and the care teams they belong to
	// (GET /v1/me)
	GetMyAccount(w http.ResponseWriter, r *http.Request)
	// Pending invitations addressed to the caller's verified email
	// (GET /v1/me/invitations)
	ListInvitationsForMe(w http.ResponseWriter, r *http.Request)
	// What needs attention for one care receiver, most important first
	// (GET /v1/receivers/{receiverId}/attention)
	ListNeedsAttention(w http.ResponseWriter, r *http.Request, receiverId string, params ListNeedsAttentionParams)
	// Each tracker's next scheduled entry, soonest first
	// (GET /v1/receivers/{receiverId}/coming-up)
	ListComingUp(w http.ResponseWriter, r *http.Request, receiverId string, params ListComingUpParams)
	// Write a journal note about this care receiver's day
	// (POST /v1/receivers/{receiverId}/journal-notes)
	AddJournalNote(w http.ResponseWriter, r *http.Request, receiverId string)
	// One day of one care receiver, in time order
	// (GET /v1/receivers/{receiverId}/timeline)
	GetDayTimeline(w http.ResponseWriter, r *http.Request, receiverId string, params GetDayTimelineParams)
	// Every tracker of one care receiver, active and paused
	// (GET /v1/receivers/{receiverId}/trackers)
	ListReceiverTrackers(w http.ResponseWriter, r *http.Request, receiverId string)
	// Create a tracker for an active care receiver (admin only)
	// (POST /v1/receivers/{receiverId}/trackers)
	AddTracker(w http.ResponseWriter, r *http.Request, receiverId string)
	// The occurrences Quick log's picker leads with
	// (GET /v1/receivers/{receiverId}/waiting)
	ListWaitingEntries(w http.ResponseWriter, r *http.Request, receiverId string)
	// Remove this schedule? — Remove (admin only)
	// (DELETE /v1/schedules/{scheduleId})
	RemoveSchedule(w http.ResponseWriter, r *http.Request, scheduleId string)
	// A schedule's Save, for an existing schedule (admin only)
	// (PUT /v1/schedules/{scheduleId})
	ChangeSchedule(w http.ResponseWriter, r *http.Request, scheduleId string)
	// Create a care team; the caller becomes its first admin
	// (POST /v1/teams)
	CreateTeam(w http.ResponseWriter, r *http.Request)
	// The care team's care receivers, oldest first
	// (GET /v1/teams/{teamId}/receivers)
	ListTeamReceivers(w http.ResponseWriter, r *http.Request, teamId string)
	// The tracker template catalogue
	// (GET /v1/tracker-templates)
	ListTemplates(w http.ResponseWriter, r *http.Request)
	// One tracker, with what is wrong with it right now
	// (GET /v1/trackers/{trackerId})
	GetTrackerDetail(w http.ResponseWriter, r *http.Request, trackerId string)
	// Edit tracker's Save (admin only)
	// (PUT /v1/trackers/{trackerId})
	EditTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// A tracker's entries, newest first
	// (GET /v1/trackers/{trackerId}/entries)
	ListTrackerEntries(w http.ResponseWriter, r *http.Request, trackerId string, params ListTrackerEntriesParams)
	// Quick log's step for a picked tracker — log ad hoc, or plan
	// (POST /v1/trackers/{trackerId}/entries)
	AddEntry(w http.ResponseWriter, r *http.Request, trackerId string)
	// Pause a tracker (admin only)
	// (POST /v1/trackers/{trackerId}/pause)
	PauseTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// Resume a paused tracker (admin only)
	// (POST /v1/trackers/{trackerId}/resume)
	ResumeTracker(w http.ResponseWriter, r *http.Request, trackerId string)
	// A tracker's schedules, readable by anyone on the team
	// (GET /v1/trackers/{trackerId}/schedules)
	ListTrackerSchedules(w http.ResponseWriter, r *http.Request, trackerId string)
	// A schedule's Save, for a new schedule (admin only)
	// (POST /v1/trackers/{trackerId}/schedules)
	AddSchedule(w http.ResponseWriter, r *http.Request, trackerId string)
}

